import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
void main() => runApp(const MaterialApp(home: UserDirectoryPage(), debugShowCheckedModeBanner: false));
Future<List<dynamic>> getUsers() async { final r = await http.get(Uri.parse('https://jsonplaceholder.typicode.com/users')); if (r.statusCode != 200) throw Exception('HTTP ${r.statusCode}'); return jsonDecode(r.body) as List<dynamic>; }
class UserDirectoryPage extends StatelessWidget { const UserDirectoryPage({super.key}); @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Q11: User directory')), body: FutureBuilder<List<dynamic>>(future: getUsers(), builder: (context, s) { if (s.connectionState == ConnectionState.waiting) return const Center(child: CircularProgressIndicator()); if (s.hasError) return Center(child: Text('Error: ${s.error}')); final users = s.data!; return ListView.builder(itemCount: users.length, itemBuilder: (context, i) { final u = users[i] as Map<String, dynamic>; return ListTile(leading: CircleAvatar(child: Text('${u['id']}')), title: Text('${u['name']}'), subtitle: Text('${u['email']}'), onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => UserDetailPage(user: u)))); }); }));
}
class UserDetailPage extends StatelessWidget { final Map<String, dynamic> user; const UserDetailPage({super.key, required this.user}); @override Widget build(BuildContext context) { final address = user['address'] as Map<String, dynamic>; final company = user['company'] as Map<String, dynamic>; return Scaffold(appBar: AppBar(title: const Text('User details')), body: ListView(padding: const EdgeInsets.all(16), children: [CircleAvatar(radius: 36, child: Text('${user['name']}'.substring(0, 1), style: const TextStyle(fontSize: 28))), const SizedBox(height: 16), Text('${user['name']}', style: Theme.of(context).textTheme.headlineSmall), const SizedBox(height: 12), Text('Username: ${user['username']}'), Text('Email: ${user['email']}'), Text('Phone: ${user['phone']}'), Text('Website: ${user['website']}'), const Divider(), Text('Address: ${address['street']}, ${address['suite']}, ${address['city']} ${address['zipcode']}'), Text('Company: ${company['name']}'), Text('Catch phrase: ${company['catchPhrase']}')])); } }
